// Describe only registrations consumed here; each inject callback supplies its component props.
interface SlotDescriptor<P> { name: string; key?: string; id?: string; order?: number; label?: string; inject?: () => P }
interface ClientContext extends PluginContext {
  layout?: { selectPanel?: (id: string) => unknown };
  slots: { inject(name: string, setup: () => unknown): unknown; register<P>(descriptor: SlotDescriptor<P>, component: (props: P) => React.ReactNode): unknown };
}

const PANEL_ID = 'project-board';
const inject = ['slots', 'layout'];

function apply(ctx: ClientContext): void {
  setPluginCtx(ctx);
  try { ensureStyles(); } catch (error) { /* non-fatal */ }
  const openPanel = function () {
    try { if (ctx.layout && ctx.layout.selectPanel) ctx.layout.selectPanel(PANEL_ID); } catch (error) { /* ignore */ }
  };
  const openPanelFor = function (cwd: string) {
    requestBoardJump(cwd);
    openPanel();
  };
  ctx.slots.inject('main', function () {
    const dispose = ctx.slots.register({ name: 'main', key: PANEL_ID }, BoardPage);
    if (currentBoardLink().view === 'flow') openPanel();
    return dispose;
  });
  ctx.slots.inject('sidebar.panellist', function () {
    return ctx.slots.register({ name: 'sidebar.panellist', id: PANEL_ID, order: 50, label: '项目板' }, PanelIcon);
  });
  ctx.slots.inject('conversation.session.header.utilities', function () {
    return ctx.slots.register({
      name: 'conversation.session.header.utilities',
      id: 'project-board-jump',
      order: 40,
      inject: function () { return { onOpen: openPanelFor }; },
    }, QuickEntry);
  });
  ctx.slots.inject('tool.call.toolview', function () {
    return ctx.slots.register({ name: 'tool.call.toolview', key: 'project_board', inject: function () { return { openPanel: openPanel }; } }, ToolCard);
  });
}

